package br.com.folha.notes;
import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import com.tom_roush.pdfbox.pdmodel.*;import com.tom_roush.pdfbox.io.MemoryUsageSetting;import com.tom_roush.pdfbox.text.PDFTextStripper;import com.tom_roush.pdfbox.pdmodel.interactive.documentnavigation.outline.*;
final class StudyTools {
 static int coverColor(String id){switch(id){case "sand":return 0xFF8A7754;case "blue":return 0xFF526F94;case "rose":return 0xFF9F5F6E;case "lavender":return 0xFF80638D;default:return MainActivity.GREEN;}}
 static void pens(MainActivity a,LinearLayout tools){SharedPreferences prefs=a.getSharedPreferences("pens",0);JSONArray list;try{list=new JSONArray(prefs.getString("favorites","[]"));if(list.length()==0){for(int c:new int[]{MainActivity.INK,0xFF3562B7,0xFFB9564A})list.put(new JSONObject().put("color",c).put("width",2.2).put("pen","fountain").put("sensitivity",1).put("smoothing",1));}}catch(Exception e){list=new JSONArray();}final JSONArray slots=list;
  for(int i=0;i<slots.length();i++){final JSONObject p=slots.optJSONObject(i);if(p==null)continue;TextView b=a.button("● "+(i+1),false,()->{a.canvas.finishInput();a.pen=p.optString("pen","fountain");a.width=(float)p.optDouble("width",2.2);a.color=p.optInt("color",MainActivity.INK);a.sensitivity=(float)p.optDouble("sensitivity",1);a.smoothing=(float)p.optDouble("smoothing",1);a.canvas.pen=a.pen;a.canvas.penWidth=a.width;a.canvas.color=a.color;a.canvas.sensitivity=a.sensitivity;a.canvas.smoothing=a.smoothing;a.selectTool(0);prefs.edit().putString("pen",a.pen).putFloat("width",a.width).putFloat("sensitivity",a.sensitivity).putFloat("smoothing",a.smoothing).apply();});b.setText(" "+(i+1));android.graphics.drawable.GradientDrawable dot=new android.graphics.drawable.GradientDrawable();dot.setColor(p.optInt("color",MainActivity.INK));dot.setShape(android.graphics.drawable.GradientDrawable.OVAL);dot.setStroke(a.dp(1),0xFF96AA9D);dot.setSize(a.dp(16),a.dp(16));b.setCompoundDrawablesWithIntrinsicBounds(dot,null,null,null);b.setContentDescription("Caneta favorita "+(i+1));tools.addView(b);a.gap(tools,4);}
  tools.addView(a.button("★ Salvar caneta",false,()->{ArrayList<String> choices=new ArrayList<>();if(slots.length()<6)choices.add("Novo favorito");for(int i=0;i<slots.length();i++)choices.add("Substituir favorito "+(i+1));a.dialog().setTitle("Guardar a caneta atual").setItems(choices.toArray(new String[0]),(d,w)->{try{boolean add=slots.length()<6;int index=add?(w==0?slots.length():w-1):w;slots.put(index,new JSONObject().put("color",a.color).put("width",a.width).put("pen",a.pen).put("sensitivity",a.sensitivity).put("smoothing",a.smoothing));prefs.edit().putString("favorites",slots.toString()).apply();a.canvas.finishInput();a.saveCurrent();a.canvas.dispose();a.generation++;a.editor();}catch(Exception e){a.error("Não foi possível guardar a caneta.",e);}}).show();}));
 }
 static void versions(MainActivity a){if(a.current==null)return;a.canvas.finishInput();a.saveCurrent();final String id=a.current.id;a.worker.execute(()->{File[] versions=a.store.versions(id);a.main.post(()->{if(a.isDestroyed())return;String[] labels=new String[versions.length];for(int i=0;i<labels.length;i++)labels[i]=android.text.format.DateFormat.format("dd/MM HH:mm:ss",Long.parseLong(versions[i].getName().substring(0,13))).toString();a.dialog().setTitle("12 versões locais · recuperar como cópia").setItems(labels,(dialog,w)->a.dialog().setTitle("Recuperar esta versão?").setMessage("Será criado outro caderno. O atual será mantido.").setNegativeButton("Cancelar",null).setPositiveButton("Criar cópia",(d,b)->{a.canvas.finishInput();a.saveCurrent();a.worker.execute(()->{try{Documents.Doc restored=a.store.restoreVersion(id,versions[w]);a.main.post(()->{a.library.add(restored);a.open(restored);});}catch(Exception e){a.main.post(()->a.error("Não foi possível recuperar a versão.",e));}});}).show()).setNeutralButton("Salvar versão agora",(d,w)->a.worker.execute(()->{try{a.store.checkpoint(a.store.read(id),true);a.main.post(()->a.toast("Versão guardada neste aparelho."));}catch(Exception e){a.main.post(()->a.error("Não foi possível guardar a versão.",e));}})).setNegativeButton("Fechar",null).show();});});}
 static PDDocument pdf(MainActivity a,Documents.Doc d) throws Exception {com.tom_roush.pdfbox.android.PDFBoxResourceLoader.init(a);MemoryUsageSetting memory=MemoryUsageSetting.setupMixed(8*1024*1024);memory.setTempDir(a.getCacheDir());return PDDocument.load(a.store.pdf(d),memory);}
 static void search(MainActivity a){a.canvas.finishInput();a.saveCurrent();Documents.Doc snapshot=a.current.copy();LinearLayout box=a.column();box.setPadding(a.dp(18),0,a.dp(18),a.dp(12));EditText input=new EditText(a);input.setHint("Palavra ou expressão");box.addView(input);TextView status=a.text("Busca no texto do PDF e nos textos digitados.",12,MainActivity.MUTED,false);box.addView(status);ListView list=new ListView(a);box.addView(list,new LinearLayout.LayoutParams(-1,a.dp(300)));final int[] token={0};AlertDialog dialog=a.dialog().setTitle("Buscar no documento").setView(box).setNegativeButton("Fechar",null).setPositiveButton("Buscar",null).create();dialog.setOnDismissListener(d->token[0]++);dialog.show();dialog.getButton(-1).setOnClickListener(v->{String q=input.getText().toString().trim().toLowerCase(Locale.ROOT);if(q.isEmpty())return;final int run=++token[0];status.setText("Buscando… feche para cancelar.");a.fileWorker.execute(()->{ArrayList<String> labels=new ArrayList<>();ArrayList<Integer> pages=new ArrayList<>();try{PDDocument pdf=snapshot.pdf?pdf(a,snapshot):null;try{PDFTextStripper stripper=pdf==null?null:new PDFTextStripper();for(int i=0;i<snapshot.count&&pages.size()<200;i++){if(run!=token[0]||a.isDestroyed())return;String text="";if(pdf!=null){stripper.setStartPage(i+1);stripper.setEndPage(i+1);text=stripper.getText(pdf);}List<Ink.Stroke> objects=snapshot.pages.get(i);if(objects!=null)for(Ink.Stroke s:objects)if(s.kind.equals("text")||!s.glyph.isEmpty())text+="\n"+s.text;String folded=java.text.Normalizer.normalize(text,java.text.Normalizer.Form.NFKC).toLowerCase(Locale.ROOT),needle=java.text.Normalizer.normalize(q,java.text.Normalizer.Form.NFKC);if(folded.contains(needle)||folded.replaceAll("\\s+","").contains(needle.replaceAll("\\s+",""))){pages.add(i);labels.add("Página "+(i+1)+" · "+text.replaceAll("\\s+"," ").substring(0,Math.min(100,text.replaceAll("\\s+"," ").length())));}}}finally{if(pdf!=null)pdf.close();}a.main.post(()->{if(run!=token[0]||!dialog.isShowing())return;status.setText(pages.isEmpty()?"Sem resultados. PDFs digitalizados precisam de OCR externo.":pages.size()+" páginas encontradas (máximo 200)");list.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_list_item_1,labels));list.setOnItemClickListener((p,view,pos,row)->{dialog.dismiss();a.changePage(pages.get(pos)-a.page);});});}catch(Exception|OutOfMemoryError e){a.main.post(()->{if(run==token[0])status.setText("Não foi possível buscar neste PDF. Seu arquivo está preservado.");});}});});}
 static void outline(MainActivity a){if(!a.current.pdf){a.showPages();return;}a.canvas.finishInput();Documents.Doc doc=a.current;AlertDialog wait=a.dialog().setMessage("Lendo sumário…").setNegativeButton("Cancelar",null).create();wait.show();a.fileWorker.execute(()->{ArrayList<String> labels=new ArrayList<>();ArrayList<Integer> pages=new ArrayList<>();try(PDDocument d=pdf(a,doc)){PDDocumentOutline root=d.getDocumentCatalog().getDocumentOutline();if(root!=null)outlineItems(d,root.getFirstChild(),labels,pages,0,new HashSet<>());a.main.post(()->{if(!wait.isShowing()||a.isDestroyed())return;wait.dismiss();if(labels.isEmpty()){a.toast("Este PDF não contém sumário. Use os marcadores de página.");a.showPages();return;}a.dialog().setTitle("Sumário").setItems(labels.toArray(new String[0]),(dialog,w)->a.changePage(pages.get(w)-a.page)).setNegativeButton("Fechar",null).show();});}catch(Exception e){a.main.post(()->{wait.dismiss();a.error("Não foi possível ler o sumário.",e);});}});}
 static void outlineItems(PDDocument d,PDOutlineItem item,List<String> labels,List<Integer> pages,int depth,Set<Object> seen) throws Exception {while(item!=null&&labels.size()<500&&depth<8&&seen.add(item.getCOSObject())){PDPage page=item.findDestinationPage(d);if(page!=null){int index=d.getPages().indexOf(page);if(index>=0){labels.add(String.join("",Collections.nCopies(depth,"  "))+item.getTitle());pages.add(index);}}outlineItems(d,item.getFirstChild(),labels,pages,depth+1,seen);item=item.getNextSibling();}}
 static void reader(MainActivity a){a.canvas.finishInput();a.saveCurrent();new ReadingPanel(a).show();}
}
